script:
frappe.ui.form.on('Movimiento Inventario', {
    setup(frm) {
        // Solo mostrar bodegas activas
        ['bodega_origen', 'bodega_destino'].forEach(campo => {
            frm.set_query(campo, () => ({ filters: { activa: 1 } }));
        });
    },
    refresh(frm) {
        mostrar_bodegas(frm);
    },
    tipo_movimiento(frm) {
        mostrar_bodegas(frm);
    }
});

frappe.ui.form.on('Detalle Movimiento', {
    cantidad(frm, cdt, cdn) {
        calcular_fila(frm, cdt, cdn);
    },
    costo_unitario(frm, cdt, cdn) {
        calcular_fila(frm, cdt, cdn);
    },
    detalle_remove(frm) {
        calcular_total(frm);
    }
});

// Entrada: solo destino | Salida: solo origen | Transferencia: ambas | Ajuste: solo destino
function mostrar_bodegas(frm) {
    const tipo = frm.doc.tipo_movimiento;
    const usa_origen = ['Salida', 'Transferencia'].includes(tipo);
    const usa_destino = ['Entrada', 'Transferencia', 'Ajuste'].includes(tipo);

    frm.toggle_display('bodega_origen', usa_origen);
    frm.toggle_reqd('bodega_origen', usa_origen);
    frm.toggle_display('bodega_destino', usa_destino);
    frm.toggle_reqd('bodega_destino', usa_destino);
}

function calcular_fila(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    frappe.model.set_value(cdt, cdn, 'subtotal', flt(row.cantidad) * flt(row.costo_unitario));
    calcular_total(frm);
}

function calcular_total(frm) {
    let total = 0;
    (frm.doc.detalle || []).forEach(row => {
        total += flt(row.subtotal);
    });
    frm.set_value('total', total);
}
